CREATE DATABASE ldb_estoque;
CREATE TABLE categoria (id BIGSERIAL PRIMARY KEY, categoria VARCHAR(60) NOT NULL)CREATE TABLE produto (id BIGSERIAL PRIMARY KEY, nome VARCHAR(60) NOT NULL, id_categoria BIGINT NOT NULL, saldo NUMERIC(15, 2) NOT NULL DEFAULT 0, valor_unitario NUMERIC(15, 2) NOT NULL DEFAULT 0, CONSTRAINT fk_produto_categoria FOREIGN KEY (id_categoria) REFERENCES categoria (id));
CREATE TABLE movimento (id BIGSERIAL PRIMARY KEY, id_produto BIGINT NOT NULL, qtd NUMERIC(15, 2) NOT NULL, data_movto TIMESTAMP, datamovto TIMESTAMP NOT NULL, CONSTRAINT fk_movimento_produto FOREIGN KEY (id_produto) REFERENCES produto (id))CREATE OR REPLACE VIEW vw_categoria_valor_total AS SELECT c.id AS id_categoria, c.categoria, SUM(p.saldo * p.valor_unitario) AS valor_total FROM categoria c LEFT JOIN produto p ON p.id_categoria = c.id GROUP BY c.id, c.categoria;
